(()=>{const catalog={"gates":[{"id":"AND","title":"AND","description":"All inputs must be 1.","formula":"Y = A \u00b7 B","lesson":"An AND gate only outputs 1 when every input is 1."},{"id":"OR","title":"OR","description":"At least one input is 1.","formula":"Y = A + B","lesson":"OR is inclusive: both inputs at 1 still produce 1."},{"id":"NOT","title":"NOT","description":"Reverse one input.","formula":"Y = A\u2032","lesson":"The small output bubble means inversion. NOT has exactly one input."},{"id":"NAND","title":"NAND","description":"Invert the AND result.","formula":"Y = (A \u00b7 B)\u2032","lesson":"NAND is universal: combinations of NAND gates can implement any Boolean function."},{"id":"NOR","title":"NOR","description":"Invert the OR result.","formula":"Y = (A + B)\u2032","lesson":"NOR is universal. Its output is 1 only when all inputs are 0."},{"id":"XOR","title":"XOR","description":"An odd number of inputs is 1.","formula":"Y = A \u2295 B","lesson":"For two inputs XOR means different. With 3 or 4 inputs, it means ODD parity\u2014not exactly one 1."},{"id":"XNOR","title":"XNOR","description":"An even number of inputs is 1.","formula":"Y = A \u2299 B","lesson":"For two inputs XNOR means equal. With 3 or 4 inputs, it means EVEN parity\u2014not that all inputs are equal."},{"id":"BUFFER","title":"BUFFER","description":"Keep the input unchanged.","formula":"Y = A","lesson":"A buffer has one input. It preserves the logic value; electrical drive strength is not modeled."}],"circuits":[{"id":"half-adder","title":"Half adder","inputs":["A","B"],"outputs":{"Sum":"s","Carry":"c"},"nodes":[{"id":"s","gate":"XOR","refs":["A","B"]},{"id":"c","gate":"AND","refs":["A","B"]}],"formula":["Sum = A \u2295 B","Carry = A \u00b7 B"],"lesson":["Adds two one-bit values. It has no carry-in.","Read Carry:Sum as a two-bit number; 1 + 1 = 10\u2082, not a single output of 2."]},{"id":"full-adder","title":"Full adder","inputs":["A","B","Cin"],"outputs":{"Sum":"s","Cout":"c"},"nodes":[{"id":"x","gate":"XOR","refs":["A","B"]},{"id":"s","gate":"XOR","refs":["x","Cin"]},{"id":"a","gate":"AND","refs":["A","B"]},{"id":"b","gate":"AND","refs":["x","Cin"]},{"id":"c","gate":"OR","refs":["a","b"]}],"formula":["Sum = A \u2295 B \u2295 Cin","Cout = AB + Cin(A \u2295 B)"],"lesson":["Includes a carry-in, so three one-bit values are added.","Cout:Sum represents A + B + Cin. Connect Cout to the next stage\u2019s Cin for a ripple adder."]},{"id":"half-subtractor","title":"Half subtractor","inputs":["A","B"],"outputs":{"Diff":"d","Borrow":"b"},"nodes":[{"id":"n","gate":"NOT","refs":["A"]},{"id":"d","gate":"XOR","refs":["A","B"]},{"id":"b","gate":"AND","refs":["n","B"]}],"formula":["Diff = A \u2295 B","Borrow = A\u2032B"],"lesson":["Subtracts B from A. Operand order matters.","When A=0 and B=1, Diff=1 with Borrow=1. This is binary subtraction, not an ordinary negative output bit."]},{"id":"full-subtractor","title":"Full subtractor","inputs":["A","B","Bin"],"outputs":{"Diff":"d","Bout":"b"},"nodes":[{"id":"x","gate":"XOR","refs":["A","B"]},{"id":"d","gate":"XOR","refs":["x","Bin"]},{"id":"na","gate":"NOT","refs":["A"]},{"id":"nx","gate":"NOT","refs":["x"]},{"id":"p","gate":"AND","refs":["na","B"]},{"id":"q","gate":"AND","refs":["nx","Bin"]},{"id":"b","gate":"OR","refs":["p","q"]}],"formula":["Diff = A \u2295 B \u2295 Bin","Bout = A\u2032B + (A \u2295 B)\u2032Bin"],"lesson":["Computes A \u2212 B \u2212 Bin.","Bout indicates that the next higher stage must supply a borrow; Diff = (A \u2212 B \u2212 Bin) mod 2."]},{"id":"mux-2","title":"2:1 multiplexer","inputs":["D0","D1","S"],"outputs":{"Y":"y"},"nodes":[{"id":"ns","gate":"NOT","refs":["S"]},{"id":"a","gate":"AND","refs":["D0","ns"]},{"id":"b","gate":"AND","refs":["D1","S"]},{"id":"y","gate":"OR","refs":["a","b"]}],"formula":["Y = S\u2032D0 + SD1"],"lesson":["A multiplexer selects one data input, not one output.","S=0 selects D0; S=1 selects D1. Changing an unselected input does not affect Y."]},{"id":"mux-4","title":"4:1 multiplexer","inputs":["D0","D1","D2","D3","S1","S0"],"outputs":{"Y":"y"},"nodes":[{"id":"n1","gate":"NOT","refs":["S1"]},{"id":"n0","gate":"NOT","refs":["S0"]},{"id":"p0","gate":"AND","refs":["D0","n1","n0"]},{"id":"p1","gate":"AND","refs":["D1","n1","S0"]},{"id":"p2","gate":"AND","refs":["D2","S1","n0"]},{"id":"p3","gate":"AND","refs":["D3","S1","S0"]},{"id":"y","gate":"OR","refs":["p0","p1","p2","p3"]}],"formula":["Y = D[2S1 + S0]"],"lesson":["S1 is the most significant select bit. 00/01/10/11 select D0/D1/D2/D3.","There are six independent inputs, so the full truth table has 64 rows."]},{"id":"demux-2","title":"1:2 demultiplexer","inputs":["D","S"],"outputs":{"Y0":"a","Y1":"b"},"nodes":[{"id":"ns","gate":"NOT","refs":["S"]},{"id":"a","gate":"AND","refs":["D","ns"]},{"id":"b","gate":"AND","refs":["D","S"]}],"formula":["Y0 = DS\u2032","Y1 = DS"],"lesson":["Routes one data input to one selected output.","The unselected output is 0. It is not a multiplexer with reversed labels."]},{"id":"decoder-2","title":"2:4 decoder + enable","inputs":["A","B","EN"],"outputs":{"Y0":"p0","Y1":"p1","Y2":"p2","Y3":"p3"},"nodes":[{"id":"na","gate":"NOT","refs":["A"]},{"id":"nb","gate":"NOT","refs":["B"]},{"id":"p0","gate":"AND","refs":["EN","na","nb"]},{"id":"p1","gate":"AND","refs":["EN","na","B"]},{"id":"p2","gate":"AND","refs":["EN","A","nb"]},{"id":"p3","gate":"AND","refs":["EN","A","B"]}],"formula":["EN=0: all outputs 0","EN=1: Y[2A + B] = 1"],"lesson":["Active-high one-hot outputs. A is the MSB.","When disabled no output is asserted; this differs from a decoder without an enable input."]},{"id":"encoder-4","title":"4:2 priority encoder","inputs":["D3","D2","D1","D0"],"outputs":{"Y1":"y1","Y0":"y0","Valid":"v"},"nodes":[{"id":"n2","gate":"NOT","refs":["D2"]},{"id":"p","gate":"AND","refs":["D1","n2"]},{"id":"y1","gate":"OR","refs":["D3","D2"]},{"id":"y0","gate":"OR","refs":["D3","p"]},{"id":"v","gate":"OR","refs":["D3","D2","D1","D0"]}],"formula":["D3 > D2 > D1 > D0","Y1Y0 = highest asserted input index"],"lesson":["Unlike a basic one-hot encoder, multiple active inputs are allowed: the highest index wins.","Valid distinguishes D0=1 (code 00) from no active input (code 00, Valid=0)."]},{"id":"compare-1","title":"1-bit magnitude comparator","inputs":["A","B"],"outputs":{"LT":"l","EQ":"e","GT":"g"},"nodes":[{"id":"na","gate":"NOT","refs":["A"]},{"id":"nb","gate":"NOT","refs":["B"]},{"id":"l","gate":"AND","refs":["na","B"]},{"id":"e","gate":"XNOR","refs":["A","B"]},{"id":"g","gate":"AND","refs":["A","nb"]}],"formula":["LT = A\u2032B","EQ = A \u2299 B","GT = AB\u2032"],"lesson":["Compares unsigned one-bit values.","Exactly one of LT/EQ/GT is 1 for every valid input."]},{"id":"compare-2","title":"2-bit magnitude comparator","inputs":["A1","A0","B1","B0"],"outputs":{"LT":"l","EQ":"e","GT":"g"},"nodes":[{"id":"e1","gate":"XNOR","refs":["A1","B1"]},{"id":"e0","gate":"XNOR","refs":["A0","B0"]},{"id":"na1","gate":"NOT","refs":["A1"]},{"id":"nb1","gate":"NOT","refs":["B1"]},{"id":"na0","gate":"NOT","refs":["A0"]},{"id":"nb0","gate":"NOT","refs":["B0"]},{"id":"lp","gate":"AND","refs":["na1","B1"]},{"id":"lq","gate":"AND","refs":["e1","na0","B0"]},{"id":"gp","gate":"AND","refs":["A1","nb1"]},{"id":"gq","gate":"AND","refs":["e1","A0","nb0"]},{"id":"l","gate":"OR","refs":["lp","lq"]},{"id":"g","gate":"OR","refs":["gp","gq"]},{"id":"e","gate":"AND","refs":["e1","e0"]}],"formula":["Compare A1 vs B1 first","If equal, compare A0 vs B0"],"lesson":["Unsigned values A=2A1+A0 and B=2B1+B0.","The least-significant comparison only matters when the most-significant bits match."]},{"id":"ripple-4","title":"4-bit ripple-carry adder","inputs":["A3","A2","A1","A0","B3","B2","B1","B0","Cin"],"outputs":{"S3":"s3","S2":"s2","S1":"s1","S0":"s0","Cout":"c3"},"nodes":[{"id":"x0","gate":"XOR","refs":["A0","B0"]},{"id":"s0","gate":"XOR","refs":["x0","Cin"]},{"id":"a0","gate":"AND","refs":["A0","B0"]},{"id":"b0","gate":"AND","refs":["x0","Cin"]},{"id":"c0","gate":"OR","refs":["a0","b0"]},{"id":"x1","gate":"XOR","refs":["A1","B1"]},{"id":"s1","gate":"XOR","refs":["x1","c0"]},{"id":"a1","gate":"AND","refs":["A1","B1"]},{"id":"b1","gate":"AND","refs":["x1","c0"]},{"id":"c1","gate":"OR","refs":["a1","b1"]},{"id":"x2","gate":"XOR","refs":["A2","B2"]},{"id":"s2","gate":"XOR","refs":["x2","c1"]},{"id":"a2","gate":"AND","refs":["A2","B2"]},{"id":"b2","gate":"AND","refs":["x2","c1"]},{"id":"c2","gate":"OR","refs":["a2","b2"]},{"id":"x3","gate":"XOR","refs":["A3","B3"]},{"id":"s3","gate":"XOR","refs":["x3","c2"]},{"id":"a3","gate":"AND","refs":["A3","B3"]},{"id":"b3","gate":"AND","refs":["x3","c2"]},{"id":"c3","gate":"OR","refs":["a3","b3"]}],"formula":["Cout:S3S2S1S0 = A + B + Cin"],"lesson":["Four full-adder stages carry from bit 0 toward bit 3.","A3/B3 are the MSBs. S3\u2026S0 is the low four-bit sum; Cout is the fifth bit.","This ideal model has no propagation-delay simulation. The 512-row truth table is paginated."]}],"sequential":[{"id":"SR_NOR","title":"SR latch \u00b7 NOR","inputs":["S","R"],"width":1,"clocked":false,"rule":"10 set \u00b7 01 reset \u00b7 00 hold \u00b7 11 forbidden","lesson":["Active-high, level-sensitive, cross-coupled NOR gates.","During S=R=1, both physical outputs are 0. Releasing to 00 leaves memory indeterminate until a valid set/reset."]},{"id":"SR_NAND","title":"SR latch \u00b7 NAND","inputs":["nS","nR"],"width":1,"clocked":false,"rule":"01 set \u00b7 10 reset \u00b7 11 hold \u00b7 00 forbidden","lesson":["Inputs nS/nR are active-low. A leading n means inversion.","During nS=nR=0 both physical outputs are 1; after release the stored state is indeterminate."]},{"id":"D_LATCH","title":"D latch \u00b7 enable","inputs":["D","EN"],"width":1,"clocked":false,"rule":"EN=1: Q follows D \u00b7 EN=0: hold","lesson":["A transparent latch is NOT an edge-triggered flip-flop.","While EN is high, changing D changes Q immediately. Lower EN to hold the last value."]},{"id":"D_FF","title":"D flip-flop","inputs":["D"],"width":1,"clocked":true,"rule":"On \u2191CLK: Q(next) = D","lesson":["A rising-edge flip-flop samples only a 0\u21921 clock edge.","Changing D while CLK remains high does not update Q. Falling edges do not capture D."]},{"id":"SR_FF","title":"SR flip-flop","inputs":["S","R"],"width":1,"clocked":true,"rule":"On \u2191CLK: set / reset / hold; 11 forbidden","lesson":["The SR inputs are sampled on rising edges, not continuously.","S=R=1 at a rising edge is forbidden; use a valid set/reset to recover."]},{"id":"JK_FF","title":"JK flip-flop","inputs":["J","K"],"width":1,"clocked":true,"rule":"00 hold \u00b7 01 reset \u00b7 10 set \u00b7 11 toggle","lesson":["JK allows the 11 case: it toggles the stored bit.","Q(next) = JQ\u2032 + K\u2032Q on a rising edge. This ideal edge model does not simulate race-around."]},{"id":"T_FF","title":"T flip-flop","inputs":["T"],"width":1,"clocked":true,"rule":"On \u2191CLK: T=0 hold \u00b7 T=1 toggle","lesson":["Q(next) = T \u2295 Q on a rising edge.","Holding CLK high does not repeatedly toggle Q."]},{"id":"COUNTER_3","title":"3-bit up counter","inputs":["EN","RESET"],"width":3,"clocked":true,"rule":"On \u2191CLK: RESET wins; EN counts mod 8","lesson":["Synchronous active-high RESET takes effect only at a rising edge.","EN=0 holds the count. After 111 the count wraps to 000."]},{"id":"SHIFT_4","title":"4-bit shift register","inputs":["D","EN","RESET"],"width":4,"clocked":true,"rule":"On \u2191CLK: RESET wins; EN shifts D into Q0","lesson":["Shift direction is toward Q3: Q3\u2190Q2\u2190Q1\u2190Q0\u2190D.","The earliest serial bit moves toward the MSB. RESET is synchronous, not asynchronous."]},{"id":"RING_4","title":"4-bit ring counter","inputs":["EN","RESET"],"width":4,"clocked":true,"rule":"On \u2191CLK: rotate left \u00b7 RESET loads 0001","lesson":["Starting from 0001: 0001 \u2192 0010 \u2192 0100 \u2192 1000 \u2192 0001.","This demonstration starts and resets one-hot. A real all-zero ring cannot start without initialization."]},{"id":"JOHNSON_4","title":"4-bit Johnson counter","inputs":["EN","RESET"],"width":4,"clocked":true,"rule":"On \u2191CLK: shift inverted Q3 into Q0","lesson":["Starting from 0000: 0000 \u2192 0001 \u2192 0011 \u2192 0111 \u2192 1111 \u2192 1110 \u2192 1100 \u2192 1000 \u2192 0000.","The four-bit twisted-ring counter has eight states in its initialized cycle. RESET is synchronous."]}]};if(typeof module!=="undefined"&&module.exports)module.exports=catalog;if(typeof window!=="undefined")window.RadixLogicCatalog=catalog;})();
